import{_ as t,o as i,c as a,ag as e}from"./chunks/framework.DEqXEGcv.js";const k=JSON.parse('{"title":"What is SMQL?","description":"","frontmatter":{},"headers":[],"relativePath":"introduction/what-is-smql.md","filePath":"introduction/what-is-smql.md"}'),n={name:"introduction/what-is-smql.md"};function l(d,s,o,r,h,p){return i(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="what-is-smql" tabindex="-1">What is SMQL? <a class="header-anchor" href="#what-is-smql" aria-label="Permalink to &quot;What is SMQL?&quot;">​</a></h1><p><strong>SMQL (State Machine Query Language)</strong> is a database engine purpose-built for data that has a lifecycle. Instead of modeling state transitions in application code on top of a general-purpose database, SMQL makes state machines a first-class primitive.</p><h2 id="the-problem" tabindex="-1">The Problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The Problem&quot;">​</a></h2><p>Every non-trivial application manages entities that move through states: orders go from <code>draft</code> to <code>paid</code> to <code>shipped</code>; support tickets go from <code>open</code> to <code>resolved</code> to <code>closed</code>; CI pipelines go from <code>queued</code> to <code>running</code> to <code>passed</code>.</p><p>In traditional databases, you model this with a <code>status</code> column and implement transition logic, guards, and audit trails in application code. This leads to:</p><ul><li><strong>Scattered validation</strong> — guard logic lives in controllers, services, and middleware</li><li><strong>Missing audit trails</strong> — &quot;who moved this to resolved and when?&quot; requires custom logging</li><li><strong>Inconsistent transitions</strong> — different code paths allow different state changes</li><li><strong>No timeout handling</strong> — &quot;auto-close after 7 days&quot; requires external cron jobs</li><li><strong>Brittle queries</strong> — &quot;how many tickets are stuck in review for &gt; 24h?&quot; requires timestamp math</li></ul><h2 id="three-principles" tabindex="-1">Three Principles <a class="header-anchor" href="#three-principles" aria-label="Permalink to &quot;Three Principles&quot;">​</a></h2><h3 id="_1-declare-intent-not-mechanics" tabindex="-1">1. Declare Intent, Not Mechanics <a class="header-anchor" href="#_1-declare-intent-not-mechanics" aria-label="Permalink to &quot;1. Declare Intent, Not Mechanics&quot;">​</a></h3><p>A machine definition reads like a specification. States, transitions, guards, and actions are declared together, not scattered across files.</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEFINE MACHINE SupportTicket (</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  DATA</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    subject</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> REQUIRED</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    assignee : REF(Agent) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OPTIONAL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  STATES { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">open</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, triaged, in_progress, resolved, closed }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  INITIAL </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">STATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> open</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TERMINAL STATES { closed }</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TRANSITIONS {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    open</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> triaged {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      GUARD  : assignee </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SET</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      ACTION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> : NOTIFY(assignee, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ticket.assigned&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="_2-transitions-are-first-class" tabindex="-1">2. Transitions Are First-Class <a class="header-anchor" href="#_2-transitions-are-first-class" aria-label="Permalink to &quot;2. Transitions Are First-Class&quot;">​</a></h3><p>A transition is not just a status update. It carries guards (preconditions), mutations (data changes), actions (side effects), and an immutable trail entry. The engine enforces all of these atomically.</p><h3 id="_3-time-is-native" tabindex="-1">3. Time Is Native <a class="header-anchor" href="#_3-time-is-native" aria-label="Permalink to &quot;3. Time Is Native&quot;">​</a></h3><p>Timeouts are part of the transition definition. The engine manages timers internally — no cron jobs, no polling, no external schedulers.</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">in_progress </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> resolved {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  TIMEOUT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 7d </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> closed</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="how-it-compares" tabindex="-1">How It Compares <a class="header-anchor" href="#how-it-compares" aria-label="Permalink to &quot;How It Compares&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>SQL + App Code</th><th>Workflow Engines</th><th>Event Sourcing</th><th>SMQL</th></tr></thead><tbody><tr><td>State definition</td><td>Column + enum</td><td>BPMN XML</td><td>Event types</td><td><code>STATES { ... }</code></td></tr><tr><td>Transition rules</td><td>Application code</td><td>Conditions</td><td>Sagas</td><td><code>GUARD : ...</code></td></tr><tr><td>Audit trail</td><td>Custom logging</td><td>Built-in</td><td>Event log</td><td><code>TRAIL OF</code></td></tr><tr><td>Timeouts</td><td>Cron jobs</td><td>Timer events</td><td>Scheduled</td><td><code>TIMEOUT: 7d</code></td></tr><tr><td>Query by state</td><td><code>WHERE status = ?</code></td><td>API call</td><td>Projection</td><td><code>STATE IS open</code></td></tr><tr><td>Schema evolution</td><td>ALTER TABLE + migration</td><td>Redeploy</td><td>New event version</td><td><code>ALTER MACHINE</code></td></tr><tr><td>Learning curve</td><td>Low</td><td>High</td><td>High</td><td>Low</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./why-smql.html">Why SMQL?</a> — concrete use cases</li><li><a href="./quick-start.html">Quick Start</a> — install, define, spawn, transition in 5 minutes</li><li><a href="./key-concepts.html">Key Concepts</a> — machines, instances, states, transitions, trails</li></ul>`,19)])])}const g=t(n,[["render",l]]);export{k as __pageData,g as default};
